namespace sv_4ca4ad79567b4854bd69afdf2770f46a.Client.Services;

public sealed record ShipmentDetails(
    string TrackingNumber,
    string Status,
    string Location,
    DateTimeOffset EstimatedDelivery,
    IReadOnlyList<StatusUpdate> Updates);

public sealed record StatusUpdate(
    string Description,
    string Location,
    DateTimeOffset Timestamp);

namespace sv_4ca4ad79567b4854bd69afdf2770f46a.Client.Services;

public interface IShipmentService
{
    Task<ShipmentDetails?> GetShipmentAsync(string trackingNumber, CancellationToken ct);
}

using System.Net.Http.Json;

namespace sv_4ca4ad79567b4854bd69afdf2770f46a.Client.Services;

public sealed class HttpShipmentService(HttpClient http) : IShipmentService
{
    public async Task<ShipmentDetails?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        var response = await http.GetAsync($"api/shipments/{Uri.EscapeDataString(trackingNumber)}", ct);

        if (response.StatusCode == System.Net.HttpStatusCode.NotFound)
            return null;

        response.EnsureSuccessStatusCode();

        return await response.Content.ReadFromJsonAsync<ShipmentDetails>(ct);
    }
}

using sv_4ca4ad79567b4854bd69afdf2770f46a.Client.Services;

namespace sv_4ca4ad79567b4854bd69afdf2770f46a.Services;

public sealed class ServerShipmentService : IShipmentService
{
    private static readonly Dictionary<string, ShipmentDetails> SeedData = new(StringComparer.OrdinalIgnoreCase)
    {
        ["PKG-001"] = new ShipmentDetails(
            TrackingNumber: "PKG-001",
            Status: "In Transit",
            Location: "Chicago, IL",
            EstimatedDelivery: new DateTimeOffset(2026, 7, 18, 17, 0, 0, TimeSpan.FromHours(-5)),
            Updates:
            [
                new StatusUpdate("Package picked up", "New York, NY", new DateTimeOffset(2026, 7, 12, 9, 30, 0, TimeSpan.FromHours(-4))),
                new StatusUpdate("Departed facility", "New York, NY", new DateTimeOffset(2026, 7, 12, 14, 15, 0, TimeSpan.FromHours(-4))),
                new StatusUpdate("Arrived at sorting center", "Chicago, IL", new DateTimeOffset(2026, 7, 14, 6, 45, 0, TimeSpan.FromHours(-5))),
            ]),

        ["PKG-002"] = new ShipmentDetails(
            TrackingNumber: "PKG-002",
            Status: "Delivered",
            Location: "San Francisco, CA",
            EstimatedDelivery: new DateTimeOffset(2026, 7, 10, 17, 0, 0, TimeSpan.FromHours(-7)),
            Updates:
            [
                new StatusUpdate("Package picked up", "Seattle, WA", new DateTimeOffset(2026, 7, 7, 8, 0, 0, TimeSpan.FromHours(-7))),
                new StatusUpdate("In transit", "Portland, OR", new DateTimeOffset(2026, 7, 8, 12, 0, 0, TimeSpan.FromHours(-7))),
                new StatusUpdate("Out for delivery", "San Francisco, CA", new DateTimeOffset(2026, 7, 10, 7, 30, 0, TimeSpan.FromHours(-7))),
                new StatusUpdate("Delivered", "San Francisco, CA", new DateTimeOffset(2026, 7, 10, 14, 22, 0, TimeSpan.FromHours(-7))),
            ]),

        ["PKG-003"] = new ShipmentDetails(
            TrackingNumber: "PKG-003",
            Status: "Processing",
            Location: "Dallas, TX",
            EstimatedDelivery: new DateTimeOffset(2026, 7, 22, 17, 0, 0, TimeSpan.FromHours(-5)),
            Updates:
            [
                new StatusUpdate("Label created", "Dallas, TX", new DateTimeOffset(2026, 7, 14, 16, 0, 0, TimeSpan.FromHours(-5))),
            ]),
    };

    public async Task<ShipmentDetails?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        // Simulate slow backend
        await Task.Delay(1500, ct);

        SeedData.TryGetValue(trackingNumber, out var shipment);
        return shipment;
    }
}

using Microsoft.AspNetCore.Mvc;
using sv_4ca4ad79567b4854bd69afdf2770f46a.Client.Services;

namespace sv_4ca4ad79567b4854bd69afdf2770f46a.Controllers;

[ApiController]
[Route("api/[controller]")]
public class ShipmentsController(IShipmentService shipmentService) : ControllerBase
{
    [HttpGet("{trackingNumber}")]
    public async Task<IActionResult> Get(string trackingNumber, CancellationToken ct)
    {
        var shipment = await shipmentService.GetShipmentAsync(trackingNumber, ct);

        if (shipment is null)
            return NotFound();

        return Ok(shipment);
    }
}

@page "/shipments/{TrackingNumber}"
@rendermode InteractiveAuto
@using sv_4ca4ad79567b4854bd69afdf2770f46a.Client.Services
@inject IShipmentService ShipmentService
@inject ILogger<ShipmentTracker> Logger
@implements IDisposable

<PageTitle>Shipment @TrackingNumber</PageTitle>

@if (_loading)
{
    <div class="loading-placeholder">
        <p><em>Loading shipment details for @TrackingNumber...</em></p>
    </div>
}
else if (_errorMessage is not null)
{
    <div class="alert alert-danger">
        <p>@_errorMessage</p>
        <button class="btn btn-outline-danger" @onclick="RetryAsync">Retry</button>
    </div>
}
else if (_shipment is null)
{
    <div class="alert alert-warning">
        <p>No shipment found for tracking number <strong>@TrackingNumber</strong>.</p>
    </div>
}
else
{
    <h3>Shipment @_shipment.TrackingNumber</h3>
    <dl>
        <dt>Status</dt>
        <dd>@_shipment.Status</dd>
        <dt>Location</dt>
        <dd>@_shipment.Location</dd>
        <dt>Estimated Delivery</dt>
        <dd>@_shipment.EstimatedDelivery.ToString("f")</dd>
    </dl>

    <h4>Tracking History</h4>
    <table class="table">
        <thead>
            <tr>
                <th>Time</th>
                <th>Location</th>
                <th>Description</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var update in _shipment.Updates)
            {
                <tr>
                    <td>@update.Timestamp.ToString("g")</td>
                    <td>@update.Location</td>
                    <td>@update.Description</td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    [Parameter]
    public string TrackingNumber { get; set; } = default!;

    private ShipmentDetails? _shipment;
    private bool _loading;
    private string? _errorMessage;
    private CancellationTokenSource? _cts;

    protected override async Task OnParametersSetAsync()
    {
        await LoadShipmentAsync();
    }

    private async Task LoadShipmentAsync()
    {
        // Cancel any in-flight request
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = new CancellationTokenSource();
        var ct = _cts.Token;

        _loading = true;
        _errorMessage = null;
        _shipment = null;
        StateHasChanged();

        try
        {
            _shipment = await ShipmentService.GetShipmentAsync(TrackingNumber, ct);
        }
        catch (OperationCanceledException) when (ct.IsCancellationRequested)
        {
            // Navigation changed or component disposed; do nothing
            return;
        }
        catch (TaskCanceledException ex) when (ex.InnerException is TimeoutException || ex.CancellationToken != ct)
        {
            Logger.LogError(ex, "Timeout loading shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "The request timed out. Please try again.";
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "The request timed out. Please try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "Something went wrong loading shipment details. Please try again.";
        }
        finally
        {
            _loading = false;
            StateHasChanged();
        }
    }

    private async Task RetryAsync()
    {
        await LoadShipmentAsync();
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

